package mypackage5ae;

public class Loop2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int i;int j;int k;
		for (i=1;i<=7;i++) 
		{
			for(k=1;k<=7-i;k++)
			
			
				{System.out.print(" ");}
			
			for(j=1;j<=i;j++)
			
				{System.out.print("*");}
				
			
			
			System.out.println("\r");
			}
	}
}
			
	